                result.append(str(count))
            current = ch
            count = 1

    result.append(current)
    if count > 1:
        result.append(str(count))

    return "".join(result)


def decode(s):
    """Decode an RLE string, supporting run lengths with multiple digits."""
    result = []
    i = 0

    while i < len(s):
        ch = s[i]
        i += 1

        digits = []
        while i < len(s) and s[i].isdigit():
            digits.append(s[i])
            i += 1

        count = int("".join(digits)) if digits else 1
        result.append(ch * count)

    return "".join(result)
